 const fullAdministrator=admin.accountType==='administrator',permissions:string[]=admin.permissions||[],allowed=(permission:string)=>fullAdministrator||permissions.includes(permission),matchAccess=fullAdministrator||['MATCHES_MANAGE','MATCH_ATTENDANCE_MANAGE','MATCHES_CANCEL','SEPARATIONS_MANAGE'].some(permission=>permissions.includes(permission));
