function OverviewDashboard({players,separations,administrators,associations,config,career}:any){
 const activePlayers=players.filter((player:Player)=>player.active),guests=players.filter((player:Player)=>player.type==='guest'),memberAccounts=associations.filter((association:any)=>association.accountType==='member'),activeMemberAccounts=memberAccounts.filter((association:any)=>association.active),careerEnabled=Boolean(career?.enabled);
 const percentage=(value:number|undefined,fallback:number)=>`${Math.round(Number(value??fallback)*100)}%`;
 return <><div className="stat-grid overview-primary-grid"><Stat label="Jogadores ativos" value={activePlayers.length} note={`${guests.length} convidados`}/><Stat label="Separações salvas" value={separations.length} note="Histórico confirmado"/><Stat label="Administradores" value={administrators.filter((item:any)=>item.active).length} note={`${administrators.length} cadastrados`}/><Stat label="Contas de jogadores" value={memberAccounts.length} note={`${activeMemberAccounts.length} ativas`}/></div><div className="overview-system-grid"><section className="admin-card overview-system-card"><div className="overview-card-head"><div><small>ALGORITMO</small><h2>Pesos de equilíbrio</h2></div><span>100% por grupo</span></div><small>JOGADORES DE LINHA</small><div className="overview-metric-grid weights"><OverviewMetric label="Físico" value={percentage(config?.speedWeight,.35)} note="Condicionamento"/><OverviewMetric label="Técnica" value={percentage(config?.skillWeight,.25)} note="Qualidade com a bola"/><OverviewMetric label="Marcação" value={percentage(config?.markingWeight,.15)} note="Critério defensivo"/><OverviewMetric label="Inteligência tática" value={percentage(config?.tacticalIntelligenceWeight,.2)} note="Leitura de jogo"/><OverviewMetric label="Competitividade" value={percentage(config?.competitivenessWeight,.05)} note="Entrega e raça"/></div><small>GOLEIROS</small><div className="overview-metric-grid weights"><OverviewMetric label="Defesas" value={percentage(config?.goalkeeperDefensesWeight,.4)} note="Reflexo e consistência"/><OverviewMetric label="Posicionamento" value={percentage(config?.goalkeeperPositioningWeight,.25)} note="Cobertura de ângulos"/><OverviewMetric label="Segurança" value={percentage(config?.goalkeeperSafetyWeight,.2)} note="Firmeza nas ações"/><OverviewMetric label="Jogo com os pés" value={percentage(config?.goalkeeperFootworkWeight,.1)} note="Reposição e passes"/><OverviewMetric label="Liderança" value={percentage(config?.goalkeeperLeadershipWeight,.05)} note="Comando da defesa"/></div></section><section className="admin-card overview-system-card career-overview"><div className="overview-card-head"><div><small>MODO CARREIRA</small><h2>Estado das funcionalidades</h2></div><StatusBadge active={careerEnabled}/></div><div className="overview-metric-grid career-states"><OverviewStatus label="Gols e assistências" active={careerEnabled&&Boolean(career?.trackContributions)} masterEnabled={careerEnabled}/><OverviewStatus label="Cards por nível" active={careerEnabled&&Boolean(career?.cardTiersEnabled)} masterEnabled={careerEnabled}/><OverviewMetric label="Multiplicador de vitórias e derrotas" value={Number(career?.resultMomentumMultiplier??1).toFixed(1)} note="Peso do momentum de resultados"/><OverviewMetric label="Multiplicador do momentum das votações" value={Number(career?.momentumMultiplier??1).toFixed(1)} note="Peso dos destaques votados"/></div></section></div><section className="admin-card overview-activity"><h2>Atividade recente</h2>{separations.length===0?<p className="overview-empty-activity">Nenhuma separação confirmada ainda.</p>:separations.slice(0,5).map((separation:any)=><div className="activity" key={separation.id}><span>⚽</span><div><b>{separation.matchTitle}</b><small>{new Date(separation.confirmedAt).toLocaleString('pt-BR')}</small></div><em>{separation.balanceClassification}</em></div>)}</section></>
}
function OverviewMetric({label,value,note}:{label:string;value:string;note:string}){return <article className="overview-metric"><small>{label}</small><b>{value}</b><span>{note}</span></article>}

function SeparationAdminPanel({separations,config,api,reload,remove,setError,setNotice,canConfigure}:any){
 const [saving,setSaving]=useState(false);
 async function toggle(enabled:boolean){setSaving(true);setError("");try{const result=await api('/api/instance-config',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({...config,separationDraftsEnabled:enabled})});setNotice(result.message);await reload()}catch(error:any){setError(error.message)}finally{setSaving(false)}}
 const enabled=config.separationDraftsEnabled===true;
 if(!canConfigure)return <div className="separation-admin-stack"><section className="admin-card table"><div className="tr sep th"><span>Partida</span><span>Confirmação</span><span>Jogadores</span><span>Equilíbrio</span><span></span></div>{separations.map((s:any)=><div className="tr sep" key={s.id}><span><b>{s.matchTitle}</b><small>{s.matchDate||'Sem data'}</small></span><span>{new Date(s.confirmedAt).toLocaleString('pt-BR')}</span><span>{s.snapshot.blue.length+s.snapshot.yellow.length}</span><span className="status active">{s.balanceClassification}</span><button className="danger" onClick={()=>remove(s.id)}>Excluir</button></div>)}</section></div>;
 return <div className="separation-admin-stack"><section className="admin-card separation-draft-setting"><div><small>PLANEJAMENTO ANTECIPADO</small><h2>Rascunhos de Separação</h2><p>Adiciona às partidas abertas um fluxo privado para gerar, ajustar e salvar propostas com os presentes atuais. No próprio rascunho, o administrador pode fechar a lista, publicar a separação e notificar os jogadores. Esta opção é independente do Modo Carreira e vem desativada por padrão.</p></div><div className="feature-switch"><button type="button" className={enabled?'ghost':'primary'} disabled={saving} aria-pressed={enabled} onClick={()=>toggle(!enabled)}>{saving?'Salvando…':enabled?'Desativar':'Ativar'}</button><HelpTip id="help-separation-drafts" text="Quando ativado, adiciona o botão Criar ou Editar rascunho nas partidas abertas. Salvar um rascunho não fecha a lista nem envia notificações. O fechamento normal e todas as configurações do Modo Carreira continuam funcionando independentemente desta opção."/></div></section><section className="admin-card table"><div className="tr sep th"><span>Partida</span><span>Confirmação</span><span>Jogadores</span><span>Equilíbrio</span><span></span></div>{separations.map((s:any)=><div className="tr sep" key={s.id}><span><b>{s.matchTitle}</b><small>{s.matchDate||'Sem data'}</small></span><span>{new Date(s.confirmedAt).toLocaleString('pt-BR')}</span><span>{s.snapshot.blue.length+s.snapshot.yellow.length}</span><span className="status active">{s.balanceClassification}</span><button className="danger" onClick={()=>remove(s.id)}>Excluir</button></div>)}</section></div>
}
function OverviewStatus({label,active,masterEnabled}:{label:string;active:boolean;masterEnabled:boolean}){return <article className="overview-metric overview-status"><small>{label}</small><StatusBadge active={active}/><span>{masterEnabled?(active?'Disponível no sistema':'Desativado na configuração'):'Modo Carreira desativado'}</span></article>}
function StatusBadge({active}:{active:boolean}){return <strong className={active?'overview-status-badge active':'overview-status-badge'}><i></i>{active?'Ativo':'Inativo'}</strong>}
function Login({onLogin,error,setError}:any){
 const {config:brand}=useInstanceBranding();
 const [mode,setMode]=useState<'login'|'request'|'reset'>('login'),[email,setEmail]=useState('admin'),[password,setPassword]=useState('admin'),[confirmation,setConfirmation]=useState(''),[resetToken,setResetToken]=useState(''),[message,setMessage]=useState(''),[busy,setBusy]=useState(false);
 useEffect(()=>{const token=new URLSearchParams(window.location.search).get('reset');if(token){setResetToken(token);setPassword('');setMode('reset')}},[]);
 async function submit(e:any){e.preventDefault();setError('');setBusy(true);try{const r=await fetch('/api/auth',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({email,password})});const j=await r.json();if(!r.ok)setError(j.error);else await onLogin()}catch{setError('Não foi possível conectar ao servidor.')}finally{setBusy(false)}}
 async function requestReset(e:any){e.preventDefault();setError('');setMessage('');setBusy(true);try{const r=await fetch('/api/password-reset',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({email})});const j=await r.json();if(!r.ok)setError(j.error);else setMessage(j.message)}catch{setError('Não foi possível solicitar a recuperação agora.')}finally{setBusy(false)}}
 async function resetPassword(e:any){e.preventDefault();setError('');setMessage('');if(password!==confirmation){setError('As senhas informadas não coincidem.');return}setBusy(true);try{const r=await fetch('/api/password-reset',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({token:resetToken,password})});const j=await r.json();if(!r.ok)setError(j.error);else{window.history.replaceState({},'',window.location.pathname);setMessage(j.message);setPassword('');setConfirmation('');setMode('login')}}catch{setError('Não foi possível redefinir a senha agora.')}finally{setBusy(false)}}
 const copy=<div className="login-copy"><a href="/">⚽ <b>{brand.siteName}</b></a><div><span>ÁREA DO ORGANIZADOR</span><h1>O controle da pelada,<br/>do seu jeito.</h1><p>Gerencie jogadores, ajuste critérios de equilíbrio e cuide do histórico com segurança.</p></div><small>{brand.siteTagline}</small></div>;
 if(mode==='request')return <div className="login-page">{copy}<form className="login-card" onSubmit={requestReset}><div className="ball">✉️</div><h2>Recuperar senha</h2><p>Enviaremos um link de uso único para o e-mail do administrador.</p>{error&&<div className="alert error">{error}</div>}{message&&<div className="admin-notice" role="status"><span>✓</span><b>{message}</b></div>}<label>E-mail cadastrado<input type="email" value={email==='admin'?'':email} onChange={e=>setEmail(e.target.value)} autoComplete="email" required/></label><button className="primary" disabled={busy}>{busy?'Enviando…':'Enviar link de recuperação'}</button><button className="forgot login-back" type="button" onClick={()=>{setMode('login');setError('');setMessage('')}}>← Voltar ao login</button></form></div>;
 if(mode==='reset')return <div className="login-page">{copy}<form className="login-card" onSubmit={resetPassword}><div className="ball">🔐</div><h2>Criar nova senha</h2><p>O link pode ser utilizado uma única vez e expira em 30 minutos.</p>{error&&<div className="alert error">{error}</div>}<label>Nova senha<input type="password" minLength={8} value={password} onChange={e=>setPassword(e.target.value)} autoComplete="new-password" required/><small>Mínimo de 8 caracteres; não pode ser “admin”.</small></label><label>Confirmar nova senha<input type="password" minLength={8} value={confirmation} onChange={e=>setConfirmation(e.target.value)} autoComplete="new-password" required/></label><button className="primary" disabled={busy}>{busy?'Salvando…':'Redefinir senha'}</button><button className="forgot login-back" type="button" onClick={()=>{window.history.replaceState({},'',window.location.pathname);setMode('login');setError('')}}>Cancelar</button></form></div>;
 return <div className="login-page">{copy}<form className="login-card" onSubmit={submit}><div className="ball">⚽</div><h2>Bem-vindo de volta</h2><p>Entre para acessar o painel administrativo.</p>{error&&<div className="alert error">{error}</div>}{message&&<div className="admin-notice" role="status"><span>✓</span><b>{message}</b></div>}<label>Usuário ou e-mail<input value={email} onChange={e=>setEmail(e.target.value)} autoComplete="username"/></label><label>Senha<input type="password" value={password} onChange={e=>setPassword(e.target.value)} autoComplete="current-password"/></label><button className="forgot" type="button" onClick={()=>{setEmail(email==='admin'?'':email);setMode('request');setError('');setMessage('')}}>Esqueci minha senha</button><button className="primary" disabled={busy}>{busy?'Entrando…':'Entrar no painel →'}</button><a href="/">← Voltar para a área pública</a></form></div>
}
function FirstAccess({admin,onDone,setError,error}:any){const [email,setEmail]=useState(admin.email==='admin'?'':admin.email),[password,setPassword]=useState('');async function go(e:any){e.preventDefault();const r=await fetch('/api/auth',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({email,password})});const j=await r.json();if(!r.ok)setError(j.error);else onDone()}return <div className="login-page single"><form className="login-card" onSubmit={go}><div className="ball">🔐</div><h2>Proteja sua conta</h2><p>No primeiro acesso, informe seu e-mail e troque a senha padrão.</p>{error&&<div className="alert error">{error}</div>}<label>E-mail<input type="email" value={email} onChange={e=>setEmail(e.target.value)} required/></label><label>Nova senha<input type="password" minLength={8} value={password} onChange={e=>setPassword(e.target.value)} required/><small>Mínimo de 8 caracteres; não pode ser “admin”.</small></label><button className="primary">Salvar e continuar</button></form></div>}
function ProfileModal({admin,api,onClose,onChanged}:any){
 const [currentPassword,setCurrentPassword]=useState(''),[newPassword,setNewPassword]=useState(''),[confirmation,setConfirmation]=useState(''),[error,setError]=useState(''),[saving,setSaving]=useState(false);
 async function save(e:any){e.preventDefault();setError('');if(newPassword!==confirmation){setError('A confirmação não corresponde à nova senha.');return}setSaving(true);try{const response=await api('/api/profile/password',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({currentPassword,newPassword,confirmation})});onChanged(response.message)}catch(e:any){setError(e.message)}finally{setSaving(false)}}
 return <div className="modal-back"><section className="profile-modal" role="dialog" aria-modal="true" aria-labelledby="profile-title"><button className="close" type="button" onClick={onClose} aria-label="Fechar perfil">×</button><div className="profile-heading"><span>{admin.email.slice(0,2).toUpperCase()}</span><div><small>MINHA CONTA</small><h2 id="profile-title">Perfil do administrador</h2></div></div><div className="profile-info"><span><small>E-mail</small><b>{admin.email}</b></span><span><small>Cadastrado em</small><b>{admin.createdAt?new Date(admin.createdAt).toLocaleDateString('pt-BR'):'Não informado'}</b></span></div><form className="profile-password" onSubmit={save}><h3>Alterar senha</h3><p>Confirme sua senha atual e escolha uma nova senha com pelo menos 8 caracteres.</p>{error&&<div className="alert error" role="alert">{error}</div>}<label>Senha atual<input type="password" value={currentPassword} onChange={e=>setCurrentPassword(e.target.value)} autoComplete="current-password" required/></label><label>Nova senha<input type="password" minLength={8} value={newPassword} onChange={e=>setNewPassword(e.target.value)} autoComplete="new-password" required/><small>Mínimo de 8 caracteres.</small></label><label>Confirmar nova senha<input type="password" minLength={8} value={confirmation} onChange={e=>setConfirmation(e.target.value)} autoComplete="new-password" required/></label><div className="editor-actions"><button type="button" className="ghost" onClick={onClose}>Cancelar</button><button className="primary" disabled={saving}>{saving?'Alterando…':'Alterar senha'}</button></div></form></section></div>
}
function PlayerForm({player,onClose,onSave,onDelete}:any){
 const [p,setP]=useState({...player,marking:player.marking??3,tacticalIntelligence:player.tacticalIntelligence??3,competitiveness:player.competitiveness??3,goalkeeperPositioning:player.goalkeeperPositioning??player.speed??3,goalExit:player.goalExit??player.marking??3,goalkeeperSafety:player.goalkeeperSafety??3,goalkeeperLeadership:player.goalkeeperLeadership??3}),[uploading,setUploading]=useState(false),[uploadError,setUploadError]=useState(""),[deleting,setDeleting]=useState(false),[deleteError,setDeleteError]=useState("");
 const set=(key:string,value:any)=>setP((current:any)=>({...current,[key]:value}));
 const goalkeeper=p.type==='goalkeeper'||p.type==='casual'||p.primaryPosition==='Goleiro';
 async function upload(file?:File){if(!file)return;setUploading(true);setUploadError("");try{const response=await fetch("/api/upload",{method:"POST",headers:{"content-type":file.type||"application/octet-stream","x-file-name":encodeURIComponent(file.name)},body:file});const payload=await response.json().catch(()=>({error:"O servidor não retornou uma resposta válida."}));if(!response.ok)throw new Error(payload.error||"Não foi possível enviar a foto.");set("photoUrl",payload.url)}catch(error:any){setUploadError(error.message)}finally{setUploading(false)}}
 function changeType(type:string){setP((current:any)=>({...current,type,primaryPosition:type==='goalkeeper'||type==='casual'?'Goleiro':current.primaryPosition==='Goleiro'?'Defesa':current.primaryPosition}))}
 function changePosition(primaryPosition:string){setP((current:any)=>({...current,primaryPosition,type:primaryPosition==='Goleiro'?'goalkeeper':current.type==='goalkeeper'||current.type==='casual'?'monthly':current.type}))}
 async function remove(){if(!confirm(`Excluir o cadastro de ${p.displayName}? O jogador sairá das listas futuras, mas todo o histórico esportivo será preservado. Esta ação não poderá ser desfeita pelo painel.`))return;setDeleting(true);setDeleteError("");try{await onDelete(p)}catch(error:any){setDeleteError(error.message)}finally{setDeleting(false)}}
 const deleteHint=player.active?'Desative o jogador, salve e abra o cadastro novamente para excluí-lo.':player.hasUserAccount?'Desassocie a conta deste jogador em “Contas de jogadores” antes de excluí-lo.':'A exclusão é lógica: partidas, súmulas e estatísticas históricas serão preservadas.';
 return <div className="modal-back"><form className="editor" onSubmit={event=>{event.preventDefault();onSave(p)}}>
  <button className="close" type="button" onClick={onClose}>×</button><h2>{p.id?'Editar jogador':'Cadastrar jogador'}</h2>
  <div className="photo-editor"><AdminAvatar player={p}/><div><label className="photo-upload">{uploading?'Enviando…':'Selecionar foto'}<input type="file" accept="image/jpeg,image/png,image/webp" disabled={uploading} onChange={event=>upload(event.target.files?.[0])}/></label>{p.photoUrl&&<button type="button" onClick={()=>set('photoUrl',null)}>Remover foto</button>}<small>JPG, PNG ou WebP de até 5 MB.</small>{uploadError&&<em>{uploadError}</em>}</div></div>
  <div className="form-grid"><label>Nome para exibição<input value={p.displayName} onChange={event=>set('displayName',event.target.value)} required/></label><label>Nome completo<input value={p.fullName} onChange={event=>set('fullName',event.target.value)} required/></label><label>Apelido<input value={p.nickname||''} onChange={event=>set('nickname',event.target.value)}/></label><label>Tipo<select value={p.type} onChange={event=>changeType(event.target.value)}>{goalkeeper?<><option value="goalkeeper">Goleiro Mensalista</option><option value="casual">Avulso</option></>:<><option value="monthly">Mensalista</option><option value="guest">Convidado</option></>}</select><small>{p.type==='casual'?'Avulso é exclusivo para goleiros pagos por partida.':goalkeeper?'Escolha entre goleiro mensalista ou avulso.':''}</small></label><label>Posição<select value={p.primaryPosition} disabled={p.type==='casual'} onChange={event=>changePosition(event.target.value)}><option>Defesa</option><option>Meio-campo</option><option>Ataque</option><option>Goleiro</option></select></label>
   {goalkeeper?<><RatingSlider label="Defesas" help="Reflexo, tempo de reação, defesas à queima-roupa e consistência." value={p.skill} onChange={value=>set('skill',value)}/><RatingSlider label="Posicionamento" help="Leitura da jogada, colocação no gol, saída do gol e cobertura de ângulos." value={p.goalkeeperPositioning} onChange={value=>set('goalkeeperPositioning',value)}/><RatingSlider label="Jogo com os Pés" help="Qualidade na reposição, passes curtos e lançamentos, participação na saída de bola." value={p.goalExit} onChange={value=>set('goalExit',value)}/><RatingSlider label="Segurança" help="Firmeza nas defesas, retenção da bola, saídas em cruzamentos e baixo índice de falhas." value={p.goalkeeperSafety} onChange={value=>set('goalkeeperSafety',value)}/><RatingSlider label="Comunicação e Liderança" help="Organização da defesa, orientação aos companheiros e comando da linha defensiva." value={p.goalkeeperLeadership} onChange={value=>set('goalkeeperLeadership',value)}/></>:<><RatingSlider label="Físico" help="Fôlego, velocidade e intensidade durante toda a partida." value={p.speed} onChange={value=>set('speed',value)}/><RatingSlider label="Técnica" help="Passe, domínio, drible, finalização e qualidade geral com a bola." value={p.skill} onChange={value=>set('skill',value)}/><RatingSlider label="Marcação" help="Desarme, posicionamento defensivo e recomposição." value={p.marking} onChange={value=>set('marking',value)}/><RatingSlider label="Inteligência Tática" help="Ocupação de espaços, movimentação, leitura de jogo e tomada de decisão." value={p.tacticalIntelligence} onChange={value=>set('tacticalIntelligence',value)}/><RatingSlider label="Competitividade" help="Entrega, raça, disputa de bolas e comprometimento." value={p.competitiveness} onChange={value=>set('competitiveness',value)}/></>}
   <label className="check"><input type="checkbox" checked={p.active} onChange={event=>set('active',event.target.checked)}/> Jogador ativo</label><label className="wide">Nomes alternativos<input value={(p.aliases||[]).join(', ')} onChange={event=>set('aliases',event.target.value.split(',').map((name:string)=>name.trim()).filter(Boolean))}/></label><label className="wide">Observações<textarea value={p.notes||''} onChange={event=>set('notes',event.target.value)}/></label>
  </div><div className="editor-actions player-editor-actions">{p.id&&<div className="player-delete-action"><button type="button" className="danger" disabled={deleting||Boolean(player.active)||Boolean(player.hasUserAccount)} onClick={remove}>{deleting?'Excluindo…':'Excluir cadastro'}</button><small>{deleteHint}</small>{deleteError&&<em role="alert">{deleteError}</em>}</div>}<div><button type="button" className="ghost" onClick={onClose}>Cancelar</button><button className="primary" disabled={uploading||deleting}>Salvar jogador</button></div></div>
 </form></div>
}
function Admins({admins,api,reload,setError,setNotice}:any){const [email,setEmail]=useState(''),[password,setPassword]=useState('');async function add(e:any){e.preventDefault();setError("");setNotice("");try{await api('/api/administrators',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({email,password})});setEmail('');setPassword('');setNotice('Administrador cadastrado com sucesso.');await reload()}catch(e:any){setError(e.message)}}async function toggle(a:any){setError("");setNotice("");try{await api('/api/administrators',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({id:a.id,active:!a.active})});setNotice(a.active?'Administrador desativado com sucesso.':'Administrador ativado com sucesso.');await reload()}catch(e:any){setError(e.message)}}return <><form className="inline-form" onSubmit={add}><input type="email" placeholder="novo@administrador.com" value={email} onChange={e=>setEmail(e.target.value)} required/><input type="password" minLength={8} placeholder="Senha inicial (8+ caracteres)" value={password} onChange={e=>setPassword(e.target.value)} required/><button className="primary">Cadastrar administrador</button></form><section className="admin-card table"><div className="tr admin-tr th"><span>E-mail</span><span>Cadastro</span><span>Atualização</span><span>Status</span><span></span></div>{admins.map((a:any)=><div className="tr admin-tr" key={a.id}><span><b>{a.email}</b></span><span>{new Date(a.createdAt).toLocaleDateString('pt-BR')}</span><span>{new Date(a.updatedAt).toLocaleDateString('pt-BR')}</span><span className={a.active?'status active':'status'}>{a.active?'Ativo':'Inativo'}</span><button className="ghost" onClick={()=>toggle(a)}>{a.active?'Desativar':'Ativar'}</button></div>)}</section></>}
function ModeratorPanel({data,api,reload,setError,setNotice}:any){
 const moderators=(data.accounts||[]).filter((account:any)=>account.role==='moderator'),members=(data.accounts||[]).filter((account:any)=>account.role!=='moderator'&&account.active),definitions=data.permissionDefinitions||[];
 const [candidate,setCandidate]=useState<any>(null);
 return <section className="moderator-admin"><div className="admin-card moderator-intro"><div><small>ACESSO INTERMEDIÁRIO</small><h2>Perfil moderador</h2><p>Moderadores continuam vinculados às suas contas e jogadores. Eles recebem somente as permissões selecionadas e nunca podem promover, reverter ou configurar outros moderadores.</p></div><b>{moderators.length}<span>moderadores</span></b></div><section className="admin-card moderator-permission-catalog"><div><small>PERMISSÕES CONFIGURÁVEIS</small><h2>Acessos que podem ser concedidos</h2><p>Estas permissões podem ser escolhidas durante a promoção e alteradas individualmente depois.</p></div><div className="moderator-permission-grid">{definitions.map((definition:any)=><article key={definition.key}><span className="moderator-permission-check">✓</span><span><b>{definition.label}</b><small>{definition.description}</small></span></article>)}</div></section>{moderators.map((account:any)=><ModeratorPermissionEditor key={account.id} account={account} definitions={definitions} api={api} reload={reload} setError={setError} setNotice={setNotice}/>)}<section className="admin-card moderator-candidates"><h2>Contas disponíveis</h2><p>Escolha uma conta comum e defina os acessos antes de concluir a promoção.</p><div>{members.length?members.map((account:any)=><article key={account.id}><span><b>{account.playerName||account.email}</b><small>{account.playerName?account.email:'Sem jogador associado'}</small></span><button className="promote-account" onClick={()=>setCandidate(account)}>Configurar e promover</button></article>):<p className="player-table-empty">Nenhuma conta comum disponível.</p>}</div></section>{candidate&&<ModeratorPromotionModal account={candidate} definitions={definitions} api={api} reload={reload} setError={setError} setNotice={setNotice} onClose={()=>setCandidate(null)}/>}</section>
}
function ModeratorPromotionModal({account,definitions,api,reload,setError,setNotice,onClose}:any){
 const [selected,setSelected]=useState<string[]>([]),[busy,setBusy]=useState(false);
 function toggle(permission:string){setSelected(current=>current.includes(permission)?current.filter(item=>item!==permission):[...current,permission])}
 async function promote(){setBusy(true);setError('');try{const result=await api('/api/moderators',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({accountId:account.id,permissions:selected})});setNotice(result.message);onClose();await reload()}catch(error:any){setError(error.message)}finally{setBusy(false)}}
 return <div className="modal-back"><section className="editor moderator-promotion-modal"><button className="close" type="button" onClick={onClose}>×</button><div className="ball">◇</div><h2>Promover para moderador</h2><p><b>{account.playerName||account.email}</b>{account.playerName&&<> · {account.email}</>}</p><div className="moderator-permission-grid">{definitions.map((definition:any)=><label key={definition.key} className={selected.includes(definition.key)?'selected':''}><input type="checkbox" checked={selected.includes(definition.key)} onChange={()=>toggle(definition.key)}/><span><b>{definition.label}</b><small>{definition.description}</small></span></label>)}</div><small className="moderator-promotion-note">É permitido criar um moderador sem acessos e concedê-los posteriormente.</small><div className="editor-actions"><button type="button" className="ghost" disabled={busy} onClick={onClose}>Cancelar</button><button type="button" className="primary" disabled={busy} onClick={promote}>{busy?'Promovendo…':`Promover com ${selected.length} permissão(ões)`}</button></div></section></div>
}
function ModeratorPermissionEditor({account,definitions,api,reload,setError,setNotice}:any){
 const [selected,setSelected]=useState<string[]>(account.permissions||[]),[busy,setBusy]=useState(false);
 useEffect(()=>setSelected(account.permissions||[]),[account.permissions]);
 function toggle(permission:string){setSelected(current=>current.includes(permission)?current.filter(item=>item!==permission):[...current,permission])}
 async function save(){setBusy(true);setError('');try{const result=await api('/api/moderators',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({accountId:account.id,permissions:selected})});setNotice(result.message);await reload()}catch(error:any){setError(error.message)}finally{setBusy(false)}}
 async function revert(){if(!confirm(`Remover o perfil moderador de ${account.email}? A conta voltará a ser um usuário comum e perderá todos os acessos adicionais.`))return;setBusy(true);setError('');try{const result=await api(`/api/moderators?accountId=${encodeURIComponent(account.id)}`,{method:'DELETE'});setNotice(result.message);await reload()}catch(error:any){setError(error.message)}finally{setBusy(false)}}
 return <section className="admin-card moderator-editor"><header><div><small>MODERADOR</small><h2>{account.playerName||account.email}</h2><p>{account.playerName&&account.email}</p></div><span className={account.active?'status active':'status'}>{account.active?'Ativo':'Inativo'}</span></header><div className="moderator-permission-grid">{definitions.map((definition:any)=><label key={definition.key} className={selected.includes(definition.key)?'selected':''}><input type="checkbox" checked={selected.includes(definition.key)} onChange={()=>toggle(definition.key)}/><span><b>{definition.label}</b><small>{definition.description}</small></span></label>)}</div><footer><button className="danger" disabled={busy} onClick={revert}>Voltar para usuário comum</button><button className="primary" disabled={busy} onClick={save}>{busy?'Salvando…':'Salvar permissões'}</button></footer></section>
}
function MemberAssociations({associations,api,reload,setError,setNotice}:any){
 const [resetAccount,setResetAccount]=useState<any>(null),[promotingId,setPromotingId]=useState<string|null>(null),[demotingId,setDemotingId]=useState<string|null>(null);
 async function remove(account:any){if(!account.playerId||!confirm(`Desassociar o login ${account.email} do jogador ${account.playerName}? O usuário poderá selecionar outro jogador no próximo acesso.`))return;setError("");setNotice("");try{const result=await api(`/api/member-associations?id=${encodeURIComponent(account.id)}&type=${encodeURIComponent(account.accountType)}`,{method:'DELETE'});setNotice(result.message);await reload()}catch(error:any){setError(error.message)}}
 async function promote(account:any){const playerDescription=account.playerName?` e continuará associada ao jogador ${account.playerName}`:'';if(!confirm(`Promover ${account.email} para administrador?\n\nA conta manterá a senha atual${playerDescription}. Essa alteração concede acesso completo ao painel administrativo e poderá ser revertida nesta mesma tela.`))return;setError('');setNotice('');setPromotingId(account.id);try{const result=await api('/api/member-associations/promote',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({accountId:account.id})});setNotice(result.message);await reload()}catch(error:any){setError(error.message)}finally{setPromotingId(null)}}
 async function demote(account:any){const playerDescription=account.playerName?` e continuará associada ao jogador ${account.playerName}`:'';if(!confirm(`Voltar ${account.email} para uma conta de jogador?\n\nA senha atual${playerDescription} será preservada. A conta perderá o acesso administrativo e suas sessões web de administrador serão encerradas.`))return;setError('');setNotice('');setDemotingId(account.id);try{const result=await api('/api/member-associations/demote',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({accountId:account.id})});setNotice(result.message);await reload()}catch(error:any){setError(error.message)}finally{setDemotingId(null)}}
 return <section className="member-associations"><div className="admin-card association-summary"><div><b>{associations.length}</b><span>contas cadastradas</span></div><div><b>{associations.filter((item:any)=>item.playerId).length}</b><span>jogadores associados</span></div><p>Contas comuns e administradores podem ter um jogador. Cada jogador aceita somente um login, independentemente do tipo da conta. Contas promovidas por esta tela podem voltar a ser usuários sem perder senha ou associação; administradores cadastrados diretamente não podem ser revertidos.</p></div><div className="admin-card table"><div className="tr member-association-tr th"><span>Login</span><span>Jogador associado</span><span>Tipo / posição</span><span>Cadastro</span><span>Último acesso</span><span>Ações</span></div>{associations.length?associations.map((item:any)=><div className="tr member-association-tr" key={`${item.accountType}-${item.id}`}><span><b>{item.email}</b><small>{item.accountType==='administrator'?(item.canDemote?'Administrador promovido':'Administrador direto'):item.active?'Conta de jogador ativa':'Conta de jogador inativa'}</small></span><span>{item.playerName?<b>{item.playerName}</b>:<em>Sem associação</em>}</span><span>{item.playerName?`${playerTypeLabel(item.playerType)} · ${item.primaryPosition}`:'—'}</span><span>{new Date(item.createdAt).toLocaleDateString('pt-BR')}</span><span>{item.lastLoginAt?new Date(item.lastLoginAt).toLocaleString('pt-BR'):'Nunca acessou'}</span><span className="association-account-actions">{item.accountType==='member'&&<><button className="ghost" onClick={()=>setResetAccount(item)}>Redefinir senha</button><button className="promote-account" disabled={promotingId===item.id} onClick={()=>promote(item)}>{promotingId===item.id?'Promovendo…':'Tornar administrador'}</button></>}{item.canDemote&&<button className="demote-account" disabled={demotingId===item.id} onClick={()=>demote(item)}>{demotingId===item.id?'Revertendo…':'Voltar para usuário'}</button>}{item.playerId?<button className="danger" onClick={()=>remove(item)}>Desassociar</button>:item.accountType==='administrator'?<span className="status">Sem jogador associado</span>:<span className="status">Aguardando jogador</span>}</span></div>):<div className="player-table-empty">Nenhuma conta cadastrada.</div>}</div>{resetAccount&&<MemberPasswordResetModal account={resetAccount} api={api} onClose={()=>setResetAccount(null)} onSaved={async(message:string)=>{setResetAccount(null);setNotice(message);await reload()}}/>}</section>
}

function MemberPasswordResetModal({account,api,onClose,onSaved}:any){
 const [password,setPassword]=useState(''),[confirmation,setConfirmation]=useState(''),[visible,setVisible]=useState(false),[saving,setSaving]=useState(false),[error,setError]=useState('');
 async function save(event:any){event.preventDefault();setError('');if(password.length<8){setError('A senha temporária deve ter pelo menos 8 caracteres.');return}if(password!==confirmation){setError('A confirmação não corresponde à senha temporária.');return}setSaving(true);try{const result=await api('/api/member-associations/password',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({accountId:account.id,password,confirmation})});await onSaved(result.message)}catch(cause:any){setError(cause.message)}finally{setSaving(false)}}
 return <div className="modal-back"><form className="editor member-password-reset-editor" onSubmit={save}><button className="close" type="button" onClick={onClose}>×</button><div className="ball">🔐</div><h2>Redefinir senha do jogador</h2><p>Defina uma senha temporária para <b>{account.email}</b>. Todas as sessões atuais serão encerradas imediatamente.</p>{error&&<div className="alert error" role="alert">{error}</div>}<label>Senha temporária<input type={visible?'text':'password'} minLength={8} value={password} onChange={event=>setPassword(event.target.value)} autoComplete="new-password" required/><small>Mínimo de 8 caracteres; não pode ser “admin”.</small></label><label>Confirmar senha temporária<input type={visible?'text':'password'} minLength={8} value={confirmation} onChange={event=>setConfirmation(event.target.value)} autoComplete="new-password" required/></label><label className="check"><input type="checkbox" checked={visible} onChange={event=>setVisible(event.target.checked)}/> Mostrar senha durante a conferência</label><div className="association-reset-warning"><b>Compartilhe com segurança</b><span>Informe a senha temporária diretamente ao jogador. Ela não será exibida novamente pelo sistema.</span></div><div className="editor-actions"><button type="button" className="ghost" onClick={onClose}>Cancelar</button><button className="primary" disabled={saving}>{saving?'Redefinindo…':'Redefinir senha'}</button></div></form></div>
}
function HelpTip({id,text}:{id:string,text:string}){
 return <span className="help-tip"><button type="button" aria-label="Ver explicação" aria-describedby={id}>?</button><span id={id} role="tooltip">{text}</span></span>
}
function InstanceConfigForm({config,api,reload,refreshBranding,setError,setNotice}:any){
 const [c,setC]=useState({...config}),[saving,setSaving]=useState(false),[uploading,setUploading]=useState<"logoUrl"|"faviconUrl"|"shareImageUrl"|null>(null);
 useEffect(()=>setC({...config}),[config]);
 const set=(key:string,value:any)=>setC((current:any)=>({...current,[key]:value}));
 async function upload(field:"logoUrl"|"faviconUrl"|"shareImageUrl",file?:File){if(!file)return;setUploading(field);setError("");try{const response=await fetch("/api/upload",{method:"POST",headers:{"content-type":file.type||"application/octet-stream","x-upload-purpose":"branding"},body:file});const payload=await response.json();if(!response.ok)throw new Error(payload.error||"Não foi possível enviar a imagem.");set(field,payload.url)}catch(error:any){setError(error.message)}finally{setUploading(null)}}
 async function save(event:any){event.preventDefault();setSaving(true);setError("");setNotice("");try{const result=await api("/api/instance-config",{method:"PUT",headers:{"content-type":"application/json"},body:JSON.stringify(c)});setNotice(result.message);await Promise.all([reload(),refreshBranding()])}catch(error:any){setError(error.message)}finally{setSaving(false)}}
 const colors=[["teamBlueName","Nome da primeira equipe"],["teamYellowName","Nome da segunda equipe"],["primaryColor","Cor principal"],["secondaryColor","Cor de destaque"],["backgroundColor","Fundo do site"],["surfaceColor","Cartões e superfícies"],["textColor","Texto principal"],["mutedColor","Texto secundário"],["teamBlueColor",`Cor do time ${c.teamBlueName}`],["teamYellowColor",`Cor do time ${c.teamYellowName}`]];
 const appColors=[["appPrimaryColor","Principal do app"],["appSecondaryColor","Destaque do app"],["appBackgroundColor","Fundo do app"],["appTextColor","Texto do app"]];
 return <form className="admin-card instance-settings" onSubmit={save}><div><h2>Personalização desta instância</h2><p>Estas definições ficam no banco desta pelada e são compartilhadas pelo site e pelo aplicativo. Nome nativo, ícone e identificadores do APK/TestFlight continuam definidos no build personalizado.</p></div><div className="instance-settings-grid"><fieldset><legend>Marca do site</legend><label>Nome completo<input value={c.siteName} maxLength={120} onChange={event=>set("siteName",event.target.value)} required/></label><label>Nome curto<input value={c.siteShortName} maxLength={40} onChange={event=>set("siteShortName",event.target.value)} required/></label><label>Frase de apoio<input value={c.siteTagline} maxLength={180} onChange={event=>set("siteTagline",event.target.value)}/></label><label>Texto do rodapé<textarea value={c.footerText} maxLength={240} onChange={event=>set("footerText",event.target.value)}/></label><div className="instance-logo-preview">{c.logoUrl?<img src={c.logoUrl} alt="Prévia do logotipo"/>:<span className="brand-mark">⚽</span>}<div><label className="photo-upload">{uploading==="logoUrl"?"Enviando…":"Selecionar logotipo"}<input type="file" accept="image/jpeg,image/png,image/webp" disabled={Boolean(uploading)} onChange={event=>upload("logoUrl",event.target.files?.[0])}/></label>{c.logoUrl&&<button type="button" className="ghost" onClick={()=>set("logoUrl",null)}>Usar ícone padrão</button>}</div></div><div className="instance-favicon-preview"><img src={c.faviconUrl||c.logoUrl||"/favicon.png"} alt="Prévia do favicon"/><div><b>Favicon</b><small>Ícone exibido na aba e nos favoritos do navegador. Recomendado: imagem quadrada de 64 × 64 px ou maior.</small><div><label className="photo-upload">{uploading==="faviconUrl"?"Enviando…":"Selecionar favicon"}<input type="file" accept=".ico,image/x-icon,image/vnd.microsoft.icon,image/jpeg,image/png,image/webp" disabled={Boolean(uploading)} onChange={event=>upload("faviconUrl",event.target.files?.[0])}/></label>{c.faviconUrl&&<button type="button" className="ghost" onClick={()=>set("faviconUrl",null)}>Usar ícone automático</button>}</div></div></div><div className="instance-share-preview"><img src={c.shareImageUrl||c.logoUrl||"/og.png"} alt="Prévia da imagem de compartilhamento"/><div><b>Imagem de compartilhamento</b><small>Exibida na prévia do WhatsApp e das redes sociais. Recomendado: 1200 × 630 px, PNG, JPEG ou WebP.</small><div><label className="photo-upload">{uploading==="shareImageUrl"?"Enviando…":"Selecionar imagem"}<input type="file" accept="image/jpeg,image/png,image/webp" disabled={Boolean(uploading)} onChange={event=>upload("shareImageUrl",event.target.files?.[0])}/></label>{c.shareImageUrl&&<button type="button" className="ghost" onClick={()=>set("shareImageUrl",null)}>Usar imagem automática</button>}</div></div></div></fieldset><fieldset><legend>Agenda padrão</legend><label>Título padrão da partida<input value={c.defaultMatchTitle} maxLength={120} onChange={event=>set("defaultMatchTitle",event.target.value)} required/></label><label>Dia da semana<select value={c.defaultMatchWeekday} onChange={event=>set("defaultMatchWeekday",Number(event.target.value))}>{["Domingo","Segunda-feira","Terça-feira","Quarta-feira","Quinta-feira","Sexta-feira","Sábado"].map((day,index)=><option value={index} key={day}>{day}</option>)}</select></label><label>Horário padrão<input type="time" value={c.defaultMatchTime} onChange={event=>set("defaultMatchTime",event.target.value)} required/></label><label>Localização padrão para meteorologia<input value={c.defaultMatchLocation||"Rio de Janeiro, Brasil"} maxLength={300} onChange={event=>set("defaultMatchLocation",event.target.value)} placeholder="Rio de Janeiro, Brasil"/><small>Usada quando a partida não tiver localização ou quando o endereço informado não for encontrado. Padrão: Rio de Janeiro, Brasil.</small></label><label>Encerrar confirmações com antecedência (minutos)<input type="number" min="0" max="10080" value={c.confirmationLeadMinutes} onChange={event=>set("confirmationLeadMinutes",Number(event.target.value))} required/></label><label>Fuso horário<input value={c.timezone} maxLength={80} onChange={event=>set("timezone",event.target.value)} required/><small>Exemplo: America/Sao_Paulo</small></label></fieldset><fieldset className="instance-feature-settings"><legend>Lista de espera de convidados</legend><label className="instance-feature-toggle"><span><b>Ativar lista de espera para convidados</b><small>Somente administradores poderão colocar convidados na lista de espera das partidas abertas. Enquanto aguardam aprovação, eles não entram no total de presentes nem na geração dos times.</small></span><input type="checkbox" checked={Boolean(c.guestPreconfirmationEnabled)} onChange={event=>set("guestPreconfirmationEnabled",event.target.checked)}/></label><label>Quantidade mínima para liberar a aprovação<input type="number" min="1" max="100" value={c.guestConfirmationThreshold??16} disabled={!c.guestPreconfirmationEnabled} onChange={event=>set("guestConfirmationThreshold",Number(event.target.value))} required/><small>Soma os presentes confirmados e os convidados na lista de espera. Ao atingir este número, o administrador poderá aprovar os convidados.</small></label></fieldset><fieldset className="instance-feature-settings"><legend>Formas de montar times</legend><label className="instance-feature-toggle"><span><b>Lista copiada do WhatsApp</b><small>Exibe a opção “Montar times” no site e “Nova” no aplicativo para importar confirmações por texto.</small></span><input type="checkbox" checked={Boolean(c.manualSeparationEnabled)} onChange={event=>set("manualSeparationEnabled",event.target.checked)}/></label><p>A geração de times pelas presenças registradas em Partidas permanece disponível mesmo quando esta opção estiver desativada.</p></fieldset><fieldset><legend>Equipes e cores do site</legend><div className="instance-color-grid">{colors.map(([key,label])=><ColorField key={key} label={label} value={c[key]} onChange={(value:string)=>set(key,value)}/>)}</div></fieldset><fieldset><legend>Aplicativo</legend><label>Título exibido no app<input value={c.appName} maxLength={120} onChange={event=>set("appName",event.target.value)} required/></label><label>Frase da tela de entrada<input value={c.appTagline} maxLength={180} onChange={event=>set("appTagline",event.target.value)}/></label><div className="instance-color-grid">{appColors.map(([key,label])=><ColorField key={key} label={label} value={c[key]} onChange={(value:string)=>set(key,value)}/>)}</div></fieldset></div><div className="settings-actions"><button className="primary" disabled={saving||Boolean(uploading)}>{saving?"Salvando…":"Salvar configurações da instância"}</button></div></form>
}
function ColorField({label,value,onChange}:{label:string;value:string;onChange(value:string):void}){const isColor=!label.startsWith("Nome da");return <label>{label}{isColor?<><input type="color" value={value} onChange={event=>onChange(event.target.value.toUpperCase())}/><input value={value} pattern="#[0-9A-Fa-f]{6}" maxLength={7} onChange={event=>onChange(event.target.value.toUpperCase())}/></>:<input value={value} maxLength={40} required onChange={event=>onChange(event.target.value)}/>}</label>}
function ConfigForm({config,api,reload,setError,setNotice}:any){
 const [c,setC]=useState(config),[saving,setSaving]=useState(false);
 const set=(k:string,v:any)=>setC((x:any)=>({...x,[k]:v}));
 const roundWeight=(value:number)=>Math.round(value*100)/100;
 const weightKeys=['speedWeight','skillWeight','markingWeight'] as const;
 function setWeight(key:typeof weightKeys[number],value:number){
  setC((current:any)=>{
   const selected=roundWeight(value),remaining=roundWeight(1-selected),others=weightKeys.filter(item=>item!==key);
   const otherTotal=Number(current[others[0]]||0)+Number(current[others[1]]||0);
   const first=otherTotal>0?roundWeight(remaining*Number(current[others[0]]||0)/otherTotal):roundWeight(remaining/2);
   return {...current,[key]:selected,[others[0]]:first,[others[1]]:roundWeight(remaining-first)};
  });
 }
 async function save(e:any){e.preventDefault();setError("");setNotice("");setSaving(true);try{const response=await api('/api/config',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify(c)});setNotice(response.message||'Configurações salvas com sucesso.');await reload()}catch(e:any){setError(e.message)}finally{setSaving(false)}}
 return <form className="admin-card settings" onSubmit={save}><div><h2>Pesos do algoritmo</h2><p>Os três critérios sempre somam 100%. Ao alterar um peso, os outros dois são ajustados proporcionalmente.</p><div className="weight-total"><span>Total configurado <HelpTip id="help-total" text="Confirma que a soma dos pesos de velocidade, habilidade e marcação está em 100%. O sistema mantém esse total automaticamente."/></span><b>{Math.round((c.speedWeight+c.skillWeight+c.markingWeight)*100)}%</b></div><div className="setting-field"><div className="setting-label"><label htmlFor="speed-weight">Peso da velocidade</label><HelpTip id="help-speed" text="Define quanto a nota de velocidade de cada jogador influencia o cálculo de equilíbrio. Quanto maior o percentual, mais o algoritmo evita concentrar jogadores rápidos no mesmo time."/><b>{Math.round(c.speedWeight*100)}%</b></div><input id="speed-weight" type="range" min="0" max="1" step=".01" value={c.speedWeight} onChange={e=>setWeight('speedWeight',+e.target.value)}/></div><div className="setting-field"><div className="setting-label"><label htmlFor="skill-weight">Peso da habilidade</label><HelpTip id="help-skill" text="Define quanto a nota de habilidade técnica influencia o equilíbrio. Um peso maior dá mais importância à distribuição dos jogadores mais habilidosos."/><b>{Math.round(c.skillWeight*100)}%</b></div><input id="skill-weight" type="range" min="0" max="1" step=".01" value={c.skillWeight} onChange={e=>setWeight('skillWeight',+e.target.value)}/></div><div className="setting-field"><div className="setting-label"><label htmlFor="marking-weight">Peso da marcação</label><HelpTip id="help-marking" text="Define quanto a capacidade de marcação e contribuição defensiva influencia o equilíbrio. Aumente para distribuir melhor os bons marcadores entre os times."/><b>{Math.round(c.markingWeight*100)}%</b></div><input id="marking-weight" type="range" min="0" max="1" step=".01" value={c.markingWeight} onChange={e=>setWeight('markingWeight',+e.target.value)}/></div></div><div><h2>Limites e tentativas</h2><div className="setting-field"><div className="setting-label"><label htmlFor="default-player-count">Quantidade padrão</label><HelpTip id="help-player-count" text="Quantidade de jogadores sugerida inicialmente na área pública. Esse valor apenas preenche o campo por padrão e pode ser alterado ao montar cada pelada."/></div><input id="default-player-count" type="number" min="2" value={c.defaultPlayerCount} onChange={e=>set('defaultPlayerCount',+e.target.value)}/></div><div className="setting-field"><div className="setting-label"><label htmlFor="position-difference">Diferença máxima por posição</label><HelpTip id="help-position-difference" text="Limita a diferença de jogadores da mesma posição entre os dois times. Valor 0 exige quantidades iguais quando possível; valor 1 permite um jogador de diferença."/></div><input id="position-difference" type="number" min="0" max="3" value={c.maximumPositionDifference} onChange={e=>set('maximumPositionDifference',+e.target.value)}/></div><div className="setting-field"><div className="setting-label"><label htmlFor="protected-players">Melhores protegidos (%)</label><HelpTip id="help-protected" text="Percentual dos jogadores com maior pontuação que o algoritmo procura distribuir primeiro entre os times, reduzindo a chance de os melhores ficarem juntos."/></div><input id="protected-players" type="number" min="0" max="100" value={c.protectedTopPlayersPercentage*100} onChange={e=>set('protectedTopPlayersPercentage',+e.target.value/100)}/></div><div className="setting-field"><div className="setting-label"><label htmlFor="algorithm-attempts">Tentativas do algoritmo</label><HelpTip id="help-attempts" text="Número de combinações de times avaliadas antes de escolher o melhor resultado. Mais tentativas podem encontrar uma separação melhor, mas aumentam o tempo de processamento."/></div><input id="algorithm-attempts" type="number" min="300" max="10000" value={c.algorithmAttempts} onChange={e=>set('algorithmAttempts',+e.target.value)}/></div></div><div className="settings-actions"><button type="button" className="ghost" onClick={()=>setC({...config,speedWeight:.48,skillWeight:.32,markingWeight:.2,maximumPositionDifference:1,protectedTopPlayersPercentage:.25,defaultPlayerCount:22})}>Restaurar padrões</button><button className="primary" disabled={saving}>{saving?'Salvando…':'Salvar configurações'}</button></div></form>
}
const lineWeightFields=[
 {key:'speedWeight',label:'Físico',help:'Fôlego, velocidade e intensidade durante toda a partida.'},
 {key:'skillWeight',label:'Técnica',help:'Passe, domínio, drible, finalização e qualidade geral com a bola.'},
 {key:'markingWeight',label:'Marcação',help:'Desarme, posicionamento defensivo e recomposição.'},
 {key:'tacticalIntelligenceWeight',label:'Inteligência Tática',help:'Ocupação de espaços, movimentação, leitura de jogo e tomada de decisão.'},
 {key:'competitivenessWeight',label:'Competitividade',help:'Entrega, raça, disputa de bolas e comprometimento.'},
] as const;
const goalkeeperWeightFields=[
 {key:'goalkeeperDefensesWeight',label:'Defesas',help:'Reflexo, tempo de reação, defesas à queima-roupa e consistência.'},
 {key:'goalkeeperPositioningWeight',label:'Posicionamento',help:'Leitura da jogada, colocação no gol, saída do gol e cobertura de ângulos.'},
 {key:'goalkeeperSafetyWeight',label:'Segurança',help:'Firmeza nas defesas, retenção da bola, saídas em cruzamentos e baixo índice de falhas.'},
 {key:'goalkeeperFootworkWeight',label:'Jogo com os Pés',help:'Qualidade na reposição, passes curtos e lançamentos, participação na saída de bola.'},
 {key:'goalkeeperLeadershipWeight',label:'Liderança',help:'Organização da defesa, orientação aos companheiros e comando da linha defensiva.'},
] as const;
function ConfigFormV2({config,api,reload,setError,setNotice}:any){
 const [c,setC]=useState({...config}),[saving,setSaving]=useState(false);
 useEffect(()=>setC({...config}),[config]);
 const set=(key:string,value:any)=>setC((current:any)=>({...current,[key]:value}));
 function setGroupWeight(fields:readonly {key:string}[],key:string,value:number){setC((current:any)=>normalizeWeightGroup(current,fields.map(field=>field.key),key,value))}
 async function save(event:any){event.preventDefault();setSaving(true);setError('');setNotice('');try{const response=await api('/api/config',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify(c)});setNotice(response.message);await reload()}catch(error:any){setError(error.message)}finally{setSaving(false)}}
 function restore(){setC({...config,speedWeight:.35,skillWeight:.25,markingWeight:.15,tacticalIntelligenceWeight:.2,competitivenessWeight:.05,goalkeeperDefensesWeight:.4,goalkeeperPositioningWeight:.25,goalkeeperSafetyWeight:.2,goalkeeperFootworkWeight:.1,goalkeeperLeadershipWeight:.05,maximumPositionDifference:1,protectedTopPlayersPercentage:.25,defaultPlayerCount:22,historicalLearningEnabled:false})}
 return <form className="admin-card settings expanded-weights" onSubmit={save}>
  <WeightGroup title="Jogadores de linha" fields={lineWeightFields} config={c} onChange={(key,value)=>setGroupWeight(lineWeightFields,key,value)}/>
  <WeightGroup title="Goleiros" fields={goalkeeperWeightFields} config={c} onChange={(key,value)=>setGroupWeight(goalkeeperWeightFields,key,value)}/>
  <div><h2>Limites e tentativas</h2><div className="setting-field"><div className="setting-label"><label htmlFor="default-player-count-v2">Quantidade padrão</label><HelpTip id="help-player-count-v2" text="Quantidade de jogadores sugerida inicialmente na área pública."/></div><input id="default-player-count-v2" type="number" min="2" value={c.defaultPlayerCount} onChange={event=>set('defaultPlayerCount',Number(event.target.value))}/></div><div className="setting-field"><div className="setting-label"><label htmlFor="position-difference-v2">Diferença máxima por posição</label><HelpTip id="help-position-difference-v2" text="Limita a diferença de jogadores da mesma posição entre os dois times."/></div><input id="position-difference-v2" type="number" min="0" max="3" value={c.maximumPositionDifference} onChange={event=>set('maximumPositionDifference',Number(event.target.value))}/></div></div>
  <div><h2>Proteção do algoritmo</h2><div className="setting-field"><div className="setting-label"><label htmlFor="protected-v2">Melhores protegidos (%)</label><HelpTip id="help-protected-v2" text="Percentual aproximado dos jogadores de linha com maior overall. O sistema arredonda para uma quantidade par, coloca exatamente metade em cada time e separa jogadores consecutivos do ranking."/></div><input id="protected-v2" type="number" min="0" max="100" value={c.protectedTopPlayersPercentage*100} onChange={event=>set('protectedTopPlayersPercentage',Number(event.target.value)/100)}/></div><div className="setting-field"><div className="setting-label"><label htmlFor="attempts-v2">Tentativas do algoritmo</label><HelpTip id="help-attempts-v2" text="Número de combinações avaliadas antes da escolha final. A quantidade de melhores protegidos permanece igual nos dois times em todas as tentativas."/></div><input id="attempts-v2" type="number" min="300" max="10000" value={c.algorithmAttempts} onChange={event=>set('algorithmAttempts',Number(event.target.value))}/></div></div>
  <section className={c.historicalLearningEnabled?'historical-learning-setting enabled':'historical-learning-setting'}><div><span>APRENDIZADO POR HISTÓRICO</span><h2>Desempenho observado nas partidas</h2><p>Quando ativado, o equilíbrio complementa o OVR com um índice limitado que considera vitórias e derrotas, saldo de gols, gols, assistências, avaliações dos colegas e o momentum das 10 partidas mais recentes. As notas manuais e o OVR exibido não são alterados.</p><small>A influência cresce gradualmente até a quinta partida registrada e nunca passa de ±0,6 ponto por jogador.</small></div><div className="historical-learning-controls"><label className="historical-learning-toggle"><input type="checkbox" checked={Boolean(c.historicalLearningEnabled)} onChange={event=>set('historicalLearningEnabled',event.target.checked)}/><b>{c.historicalLearningEnabled?'Ativado':'Desativado'}</b></label><HelpTip id="help-historical-learning" text="O índice é recalculado a cada separação usando somente partidas com placar confirmado. Jogadores com pouco histórico recebem influência reduzida. Desativar a opção faz o algoritmo voltar imediatamente às regras tradicionais, sem apagar nenhum dado."/></div></section>
  <div className="settings-actions"><button type="button" className="ghost" onClick={restore}>Restaurar padrões</button><button className="primary" disabled={saving}>{saving?'Salvando…':'Salvar configurações'}</button></div>
 </form>
}
function WeightGroup({title,fields,config,onChange}:{title:string;fields:readonly {key:string;label:string;help:string}[];config:any;onChange:(key:string,value:number)=>void}){const total=fields.reduce((sum,field)=>sum+Number(config[field.key]??0),0);return <div className="weight-group"><h2>Pesos — {title}</h2><p>As cinco disciplinas somam 100% e definem o overall atual.</p><div className="weight-total"><span>Total configurado <HelpTip id={`help-total-${title}`} text="Ao alterar um peso, os outros quatro são ajustados proporcionalmente."/></span><b>{Math.round(total*100)}%</b></div>{fields.map(field=><div className="setting-field" key={field.key}><div className="setting-label"><label htmlFor={field.key}>{field.label}</label><HelpTip id={`help-${field.key}`} text={field.help}/><b>{Math.round(Number(config[field.key]??0)*100)}%</b></div><input id={field.key} type="range" min="0" max="1" step=".01" value={config[field.key]??0} onChange={event=>onChange(field.key,Number(event.target.value))}/></div>)}</div>}
function normalizeWeightGroup(current:any,keys:string[],changed:string,next:number){const result={...current},bounded=Math.max(0,Math.min(1,Math.round(next*100)/100)),others=keys.filter(key=>key!==changed),remaining=1-bounded,total=others.reduce((sum,key)=>sum+Number(current[key]??0),0);result[changed]=bounded;let assigned=0;others.forEach((key,index)=>{const value=index===others.length-1?remaining-assigned:total>0?Math.round((remaining*Number(current[key]??0)/total)*10000)/10000:remaining/others.length;result[key]=Math.max(0,Math.round(value*10000)/10000);assigned+=result[key]});return result}

function CareerPanel({data,api,reload,setError,setNotice,canConfigure}:any){
 const [c,setC]=useState({...data.config}),[saving,setSaving]=useState(false),[open,setOpen]=useState<string|null>(null);
 useEffect(()=>setC({...data.config}),[data.config]);
 const set=(key:string,value:any)=>setC((current:any)=>({...current,[key]:value}));
 async function save(event:any){event.preventDefault();setSaving(true);setError("");setNotice("");try{const response=await api('/api/career/admin',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify(c)});setNotice(response.message);await reload()}catch(error:any){setError(error.message)}finally{setSaving(false)}}
 async function closeMatch(id:string){if(!confirm('Encerrar esta votação agora? O resultado e o momentum serão finais e os votos não poderão mais ser alterados.'))return;try{const response=await api('/api/career/admin',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({matchId:id})});setNotice(response.message);await reload()}catch(error:any){setError(error.message)}}
 async function removeVote(id:string){if(!confirm('Remover este voto? O jogador poderá votar novamente enquanto a votação estiver aberta.'))return;try{const response=await api(`/api/career/admin?voteId=${encodeURIComponent(id)}`,{method:'DELETE'});setNotice(response.message);await reload()}catch(error:any){setError(error.message)}}
 if(!canConfigure)return <CareerVoteManagement data={data} open={open} setOpen={setOpen} closeMatch={closeMatch} removeVote={removeVote}/>;
 return <div className="career-admin"><form className="admin-card career-config" onSubmit={save}><div className="career-config-head"><div><h2>Configurações do Modo Carreira</h2><p>Os momentums de vitórias/derrotas e das votações usam multiplicadores independentes. Ao virar a temporada, somente esses saldos são zerados; o histórico de partidas permanece.</p></div><div className="career-switches"><label className="career-switch"><input type="checkbox" checked={c.enabled} onChange={e=>set('enabled',e.target.checked)}/><span>{c.enabled?'Ativado':'Desativado'}</span></label><label className="career-switch contribution-switch"><input type="checkbox" checked={c.trackContributions} onChange={e=>set('trackContributions',e.target.checked)}/><span>Gols e assistências</span></label><label className="career-switch tier-switch"><input type="checkbox" checked={Boolean(c.cardTiersEnabled)} onChange={e=>set('cardTiersEnabled',e.target.checked)}/><span>Cards por nível</span></label></div></div><div className="career-config-grid"><CareerNumber label="Multiplicador de vitórias e derrotas" value={c.resultMomentumMultiplier??1} onChange={(v:number)=>set('resultMomentumMultiplier',v)} min={0} max={5}/><CareerNumber label="Multiplicador do momentum das votações" value={c.momentumMultiplier} onChange={(v:number)=>set('momentumMultiplier',v)} min={0} max={5}/><CareerNumber label="Bônus da equipe vencedora" value={c.winnerBonus} onChange={(v:number)=>set('winnerBonus',v)} min={0} max={1}/><CareerNumber label="Ônus da equipe perdedora" value={c.loserPenalty} onChange={(v:number)=>set('loserPenalty',v)} min={-1} max={0}/><CareerNumber label="Votação aberta por (dias)" value={c.votingDays} onChange={(v:number)=>set('votingDays',v)} min={1} max={30} step={1}/><CareerNumber label="Duração da temporada (meses)" value={c.seasonDurationMonths??12} onChange={(v:number)=>set('seasonDurationMonths',v)} min={1} max={120} step={1}/></div><div className="career-season-status"><span><small>TEMPORADA ATUAL</small><b>Temporada {c.seasonNumber??1}</b></span><span><small>INÍCIO</small><b>{careerDate(c.seasonStartedAt)}</b></span><span><small>PRÓXIMO RESET</small><b>{careerDate(c.nextSeasonResetAt)}</b></span><p>Ao alterar a duração, o próximo reset será reagendado a partir do momento em que estas configurações forem salvas.</p></div><CardTierThresholds config={c} set={set}/><div className="career-prizes"><section><h3>Man of the Match</h3><CareerNumber label="3º lugar" value={c.motmThird} onChange={(v:number)=>set('motmThird',v)} min={0} max={1}/><CareerNumber label="2º lugar" value={c.motmSecond} onChange={(v:number)=>set('motmSecond',v)} min={0} max={1}/><CareerNumber label="1º lugar" value={c.motmFirst} onChange={(v:number)=>set('motmFirst',v)} min={0} max={1}/></section><section><h3>Deception of the Match</h3><CareerNumber label="3º lugar" value={c.dotmThird} onChange={(v:number)=>set('dotmThird',v)} min={-1} max={0}/><CareerNumber label="2º lugar" value={c.dotmSecond} onChange={(v:number)=>set('dotmSecond',v)} min={-1} max={0}/><CareerNumber label="1º lugar" value={c.dotmFirst} onChange={(v:number)=>set('dotmFirst',v)} min={-1} max={0}/></section></div><div className="settings-actions"><button className="primary" disabled={saving}>{saving?'Salvando…':'Salvar Modo Carreira'}</button></div></form><section className="career-match-list"><div className="section-head"><div><h2>Votações por seleção</h2><p>Votos podem ser removidos somente enquanto a votação estiver aberta.</p></div></div>{data.matches.length===0?<div className="admin-card empty-admin"><b>Nenhuma partida confirmada</b><p>Registre o placar em uma separação salva para abrir a votação.</p></div>:data.matches.map((match:any)=><article className="admin-card career-match-admin" key={match.id}><button className="career-match-summary" onClick={()=>setOpen(open===match.id?null:match.id)}><div><small>{match.status==='OPEN'?'VOTAÇÃO ABERTA':'VOTAÇÃO ENCERRADA'}</small><h3>{match.matchTitle}</h3><span>{match.matchDate||'Sem data'} · encerra em {new Date(match.closesAt).toLocaleString('pt-BR')}</span></div><strong>{match.blueScore} × {match.yellowScore}</strong><em>{match.votes.length} votos</em><i>{open===match.id?'−':'+'}</i></button>{open===match.id&&<div className="career-match-body">{match.votes.length===0?<p className="empty">Nenhum voto recebido.</p>:match.votes.map((vote:any)=><div className="career-vote-row" key={vote.id}><div><b>{vote.voterName}</b><small>{new Date(vote.createdAt).toLocaleString('pt-BR')}</small></div><span><b>Melhores:</b> {vote.motm.map((entry:any,index:number)=>`${index+1}º ${entry.name}`).join(', ')}</span><span><b>Piores:</b> {vote.dotm.map((entry:any,index:number)=>`${index+1}º ${entry.name}`).join(', ')}</span>{match.status==='OPEN'&&<button className="danger" onClick={()=>removeVote(vote.id)}>Remover</button>}</div>)}{match.status==='OPEN'?<button className="danger career-close" onClick={()=>closeMatch(match.id)}>Encerrar votação antecipadamente</button>:<p className="career-final-note">Resultado final aplicado em {new Date(match.closedAt).toLocaleString('pt-BR')}. Os votos estão bloqueados.</p>}</div>}</article>)}</section></div>
}
function CareerVoteManagement({data,open,setOpen,closeMatch,removeVote}:any){return <div className="career-admin"><section className="career-match-list"><div className="section-head"><div><h2>Votações por seleção</h2><p>Votos podem ser removidos somente enquanto a votação estiver aberta.</p></div></div>{data.matches.length===0?<div className="admin-card empty-admin"><b>Nenhuma partida confirmada</b><p>Registre o placar em uma separação salva para abrir a votação.</p></div>:data.matches.map((match:any)=><article className="admin-card career-match-admin" key={match.id}><button className="career-match-summary" onClick={()=>setOpen(open===match.id?null:match.id)}><div><small>{match.status==='OPEN'?'VOTAÇÃO ABERTA':'VOTAÇÃO ENCERRADA'}</small><h3>{match.matchTitle}</h3><span>{match.matchDate||'Sem data'} · encerra em {new Date(match.closesAt).toLocaleString('pt-BR')}</span></div><strong>{match.blueScore} × {match.yellowScore}</strong><em>{match.votes.length} votos</em><i>{open===match.id?'−':'+'}</i></button>{open===match.id&&<div className="career-match-body">{match.votes.length===0?<p className="empty">Nenhum voto recebido.</p>:match.votes.map((vote:any)=><div className="career-vote-row" key={vote.id}><div><b>{vote.voterName}</b><small>{new Date(vote.createdAt).toLocaleString('pt-BR')}</small></div><span><b>Melhores:</b> {vote.motm.map((entry:any,index:number)=>`${index+1}º ${entry.name}`).join(', ')}</span><span><b>Piores:</b> {vote.dotm.map((entry:any,index:number)=>`${index+1}º ${entry.name}`).join(', ')}</span>{match.status==='OPEN'&&<button className="danger" onClick={()=>removeVote(vote.id)}>Remover</button>}</div>)}{match.status==='OPEN'?<button className="danger career-close" onClick={()=>closeMatch(match.id)}>Encerrar votação antecipadamente</button>:<p className="career-final-note">Resultado final aplicado em {new Date(match.closedAt).toLocaleString('pt-BR')}. Os votos estão bloqueados.</p>}</div>}</article>)}</section></div>}
function careerDate(value:string){if(!value)return 'A definir';const date=new Date(value);return Number.isFinite(date.getTime())?date.toLocaleString('pt-BR'):'A definir'}
function CardTierThresholds({config,set}:{config:any;set:(key:string,value:any)=>void}){
 const legendaryStart=Math.min(5,Math.round((Number(config.cardGoldMax??4.5)+.1)*10)/10);
 return <><MonthlyTeamFormationSettings config={config} set={set}/><section className={"card-tier-settings "+(config.cardTiersEnabled?'enabled':'disabled')}><div className="card-tier-settings-head"><div><h3>Níveis dos cards</h3><p>Defina a nota máxima de cada faixa. O próximo nível começa automaticamente 0,1 ponto acima.</p></div><span>{config.cardTiersEnabled?'Aplicado nos cards e na lista pública':'Pré-configurado, mas desativado'}</span></div><div className="card-tier-grid"><div className="card-tier-option bronze"><CareerNumber label="Bronze até" value={config.cardBronzeMax??2.4} onChange={(value:number)=>set('cardBronzeMax',value)} min={1} max={4.7}/></div><div className="card-tier-option silver"><CareerNumber label="Prata até" value={config.cardSilverMax??3.9} onChange={(value:number)=>set('cardSilverMax',value)} min={1.1} max={4.8}/></div><div className="card-tier-option gold"><CareerNumber label="Ouro até" value={config.cardGoldMax??4.5} onChange={(value:number)=>set('cardGoldMax',value)} min={1.2} max={4.9}/></div><div className="card-tier-option legendary"><small>Lendário</small><b>Acima de {Number(config.cardGoldMax??4.5).toFixed(1)}</b><span>A partir de {legendaryStart.toFixed(1)}</span></div></div><p className="card-tier-order">Os limites precisam estar em ordem: Bronze &lt; Prata &lt; Ouro. Todos aceitam uma casa decimal.</p></section></>
}
function MonthlyTeamFormationSettings({config,set}:{config:any;set:(key:string,value:any)=>void}){
 const fields=[['monthlyTeamGoalkeepers','Goleiros'],['monthlyTeamDefenders','Defesas'],['monthlyTeamMidfielders','Meio-campistas'],['monthlyTeamAttackers','Atacantes']] as const;
 const total=fields.reduce((sum,[key])=>sum+Number(config[key]??0),0);
 return <section className="monthly-team-settings"><div className="monthly-team-settings-head"><div><h3>Formação da Seleção do Mês</h3><p>Escolha quantos jogadores de cada posição serão premiados quando o mês for encerrado.</p></div><span><b>{total}</b> jogadores</span></div><div className="monthly-team-grid">{fields.map(([key,label])=><CareerNumber key={key} label={label} value={config[key]??({monthlyTeamGoalkeepers:1,monthlyTeamDefenders:2,monthlyTeamMidfielders:2,monthlyTeamAttackers:2} as any)[key]} onChange={(value:number)=>set(key,value)} min={0} max={11} step={1}/>)}</div><p>Formação padrão: 1 goleiro, 2 defesas, 2 meio-campistas e 2 atacantes. Alterações valem somente para meses ainda não finalizados.</p></section>
}
function CareerNumber({label,value,onChange,min,max,step=.1}:any){
 const negative=Number(value)<0;
 const descriptions:Record<string,string>={
  'Multiplicador de vitórias e derrotas':'Controla quanto o saldo de momentum recebido por vitórias e derrotas influencia o overall. O padrão 1 aplica seu valor integral; zero ignora esse saldo e valores maiores ampliam seu efeito.',
  'Multiplicador do momentum das votações':'Controla somente quanto os bônus e ônus recebidos nas votações influenciam o overall. Zero ignora apenas os votos, 1 aplica seu valor integral e valores maiores ampliam seu efeito.',
  'Bônus da equipe vencedora':'Valor acrescentado ao momentum de cada jogador do time vencedor assim que o administrador confirma o placar. Em caso de empate, nenhuma equipe recebe esse bônus.',
  'Ônus da equipe perdedora':'Valor descontado do momentum de cada jogador do time perdedor quando o placar é confirmado. Use um número negativo; empates não aplicam este ônus.',
  'Votação aberta por (dias)':'Quantidade de dias em que os participantes poderão votar depois da confirmação do placar. Ao vencer o prazo, a votação é encerrada e os resultados são aplicados automaticamente.',
  'Duração da temporada (meses)':'Quantidade de meses entre os resets automáticos. No reset, os momentums de resultados e votações voltam a zero, mas jogos, vitórias, derrotas, gols e assistências continuam no histórico.',
  'Goleiros':'Quantidade de goleiros escolhidos para a Seleção do Mês. Use zero somente quando a pelada não utilizar essa posição.',
  'Defesas':'Quantidade de jogadores da posição Defesa escolhidos para a Seleção do Mês.',
  'Meio-campistas':'Quantidade de jogadores da posição Meio-campo escolhidos para a Seleção do Mês.',
  'Atacantes':'Quantidade de jogadores da posição Ataque escolhidos para a Seleção do Mês.',
  'Bronze até':'Maior overall que ainda usa o card bronze. O nível prata começa 0,1 ponto acima deste valor.',
  'Prata até':'Maior overall que ainda usa o card prata. O nível ouro começa 0,1 ponto acima deste valor.',
  'Ouro até':'Maior overall que ainda usa o card ouro. Jogadores acima deste valor recebem o card lendário.',
 };
 const podiumDescriptions:Record<string,string>={
  '3º lugar':negative?'Redução de momentum aplicada ao jogador que terminar em 3º lugar entre os destaques negativos da votação.':'Bônus de momentum aplicado ao jogador que terminar em 3º lugar na votação de Man of the Match.',
  '2º lugar':negative?'Redução de momentum aplicada ao jogador que terminar em 2º lugar entre os destaques negativos da votação.':'Bônus de momentum aplicado ao jogador que terminar em 2º lugar na votação de Man of the Match.',
  '1º lugar':negative?'Maior redução de momentum, aplicada ao jogador mais votado como Deception of the Match.':'Maior bônus de momentum, aplicado ao jogador mais votado como Man of the Match.',
 };
 const text=descriptions[label]||podiumDescriptions[label]||'Valor usado pelo Modo Carreira no cálculo de momentum.';
 const id=`help-career-${negative?'negative':'positive'}-${label.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/gi,'-').toLowerCase()}`;
 return <label className="career-number"><span>{label}<HelpTip id={id} text={text}/></span><input type="number" value={value} min={min} max={max} step={step} onChange={event=>onChange(Number(event.target.value))}/></label>
}
function AuditPanel({data,loading,query,action,pageSize,onQuery,onAction,onPageSize,onPage}:any){
 const logs=data?.logs||[],actions=data?.actions||[],pagination=data?.pagination||{page:1,pageSize,total:0,totalPages:1},start=pagination.total?(pagination.page-1)*pagination.pageSize+1:0,end=Math.min(pagination.page*pagination.pageSize,pagination.total);
 return <section className="audit-panel" aria-busy={loading}><div className="audit-toolbar"><div><b>{pagination.total}</b><span>eventos encontrados</span></div><input placeholder="Buscar por usuário, ação ou registro…" value={query} onChange={event=>onQuery(event.target.value)}/><select value={action} onChange={event=>onAction(event.target.value)}><option value="ALL">Todas as ações</option>{actions.map((item:string)=><option key={item} value={item}>{actionLabel(item)}</option>)}</select><label className="audit-page-size"><span>Por página</span><select value={pageSize} onChange={event=>onPageSize(Number(event.target.value))}>{[10,25,50,100].map(size=><option key={size} value={size}>{size}</option>)}</select></label></div>{loading&&logs.length===0?<div className="admin-card audit-empty"><b>Carregando eventos…</b></div>:logs.length===0?<div className="admin-card audit-empty"><b>Nenhum evento encontrado</b><p>Revise os filtros ou aguarde novas atividades do sistema.</p></div>:<div className={loading?"audit-list loading":"audit-list"}>{logs.map((log:any)=><article key={log.id}><div className={`audit-icon action-${log.action.toLowerCase()}`}>{actionIcon(log.action)}</div><div className="audit-copy"><div><b>{actionLabel(log.action)}</b><span className="audit-entity">{entityLabel(log.entityType)}</span></div><p>{auditSubject(log)}</p><small>{log.administratorEmail} · {new Date(log.createdAt).toLocaleString('pt-BR')}</small>{(log.previousData||log.newData)&&<details><summary>Ver detalhes da alteração</summary><div className="audit-details">{log.previousData&&<div><b>Antes</b><pre>{JSON.stringify(log.previousData,null,2)}</pre></div>}{log.newData&&<div><b>Depois</b><pre>{JSON.stringify(log.newData,null,2)}</pre></div>}</div></details>}</div></article>)}</div>}<nav className="audit-pagination" aria-label="Paginação da auditoria"><button type="button" className="ghost" disabled={loading||pagination.page<=1} onClick={()=>onPage(pagination.page-1)}>← Anterior</button><span>Exibindo <b>{start}–{end}</b> de <b>{pagination.total}</b><small>Página {pagination.page} de {pagination.totalPages}</small></span><button type="button" className="ghost" disabled={loading||pagination.page>=pagination.totalPages} onClick={()=>onPage(pagination.page+1)}>Próxima →</button></nav></section>
}
function actionLabel(action:string){return({CREATE:'Cadastro',UPDATE:'Alteração',UPDATE_INSTANCE_CONFIGURATION:'Identidade e agenda atualizadas',DELETE:'Exclusão',ACTIVATE:'Ativação',DEACTIVATE:'Desativação',LOGIN:'Login',LOGOUT:'Saída',CHANGE_PASSWORD:'Troca de senha',PASSWORD_RESET_REQUEST:'Solicitação de recuperação',PASSWORD_RESET:'Redefinição de senha',MEMBER_PASSWORD_RESET_REQUEST:'Solicitação de recuperação do jogador',MEMBER_PASSWORD_RESET:'Redefinição de senha do jogador',ADMIN_MEMBER_PASSWORD_RESET:'Senha de jogador redefinida pelo administrador',MEMBER_PROMOTED_TO_ADMIN:'Conta promovida a administrador',ADMIN_REVERTED_TO_MEMBER:'Administrador revertido para usuário',MEMBER_PROMOTED_TO_MODERATOR:'Conta promovida a moderador',MODERATOR_PERMISSIONS_UPDATED:'Permissões do moderador atualizadas',MODERATOR_REVERTED_TO_MEMBER:'Moderador revertido para usuário',MEMBER_REGISTER:'Cadastro de jogador',MEMBER_LOGIN:'Login de jogador',MEMBER_LOGOUT:'Saída de jogador',MEMBER_ASSOCIATE:'Associação de jogador',MEMBER_DISASSOCIATE:'Desassociação de jogador',MEMBER_PROFILE_UPDATE:'Perfil atualizado pelo jogador',MATCH_CREATED:'Partida criada',MATCH_UPDATED:'Partida atualizada',MATCH_ATTENDANCE_CHANGED:'Presença alterada',MATCH_CLOSED_AND_SEPARATED:'Lista fechada e times gerados',MATCH_SEPARATION_DRAFT_CREATED:'Rascunho de separação criado',MATCH_SEPARATION_DRAFT_UPDATED:'Rascunho de separação atualizado',MATCH_CANCELLED:'Partida cancelada',CAREER_MATCH_CONFIRMED:'Placar confirmado',CAREER_VOTE:'Voto registrado',CAREER_VOTING_CLOSED:'Votação encerrada',CAREER_SEASON_RESET:'Nova temporada iniciada'} as Record<string,string>)[action]||action}
function entityLabel(entity:string){return({player:'Jogador',member_account:'Conta de jogador',configuration:'Configurações',instance_configuration:'Identidade e agenda',administrator:'Administrador',scheduled_match:'Partida agendada',separation:'Separação',separation_draft:'Rascunho de separação',career_match:'Partida do Modo Carreira',career_vote:'Voto do Modo Carreira',career_configuration:'Modo Carreira'} as Record<string,string>)[entity]||entity}
function actionIcon(action:string){return({CREATE:'＋',UPDATE:'✎',DELETE:'×',ACTIVATE:'✓',DEACTIVATE:'−',LOGIN:'→',LOGOUT:'←',CHANGE_PASSWORD:'●',PASSWORD_RESET_REQUEST:'✉',PASSWORD_RESET:'◆',MEMBER_PASSWORD_RESET_REQUEST:'✉',MEMBER_PASSWORD_RESET:'◆',ADMIN_MEMBER_PASSWORD_RESET:'🔐',MEMBER_PROMOTED_TO_ADMIN:'★',ADMIN_REVERTED_TO_MEMBER:'↩',MEMBER_PROMOTED_TO_MODERATOR:'◇',MODERATOR_PERMISSIONS_UPDATED:'☑',MODERATOR_REVERTED_TO_MEMBER:'↩',MATCH_CREATED:'📅',MATCH_UPDATED:'✎',MATCH_ATTENDANCE_CHANGED:'✓',MATCH_CLOSED_AND_SEPARATED:'⚽',MATCH_CANCELLED:'×',CAREER_SEASON_RESET:'↻'} as Record<string,string>)[action]||'•'}
function auditSubject(log:any){const data=log.newData||log.previousData||{};if(log.entityType==='player')return data.displayName||data.display_name||data.fullName||`Jogador ${log.entityId?.slice(0,8)||''}`;if(log.entityType==='administrator'||log.entityType==='member_account')return data.email||log.administratorEmail;if(log.entityType==='configuration')return 'Critérios de equilíbrio do sistema';if(log.entityType==='instance_configuration')return data.siteName||'Identidade da instância';if(log.entityType==='career_configuration')return 'Parâmetros de momentum e votação';if(log.entityType==='scheduled_match')return data.title||data.playerName||`Partida ${log.entityId?.slice(0,8)||''}`;if(log.entityType==='separation'||log.entityType==='career_match')return data.matchTitle||data.match_title||`Partida ${log.entityId?.slice(0,8)||''}`;if(log.entityType==='career_vote')return data.voterName||data.voter_player_id||`Voto ${log.entityId?.slice(0,8)||''}`;return log.entityId||'Registro do sistema'}
function Stat({label,value,note}:any){return <article className="stat"><small>{label}</small><b>{value}</b><span>{note}</span></article>}
function AdminAvatar({player}:{player:Player}){return <PlayerPhoto photoUrl={player.photoUrl} name={player.displayName} className="admin-photo"/>}
function PlayerTables({players,sort,onSort,onEdit}:{players:Player[];sort:PlayerSort;onSort:(key:PlayerSortKey)=>void;onEdit:(player:Player)=>void}){
 const goalkeepers=players.filter(player=>player.type==='goalkeeper'||player.type==='casual'||player.primaryPosition==='Goleiro');
 const linePlayers=players.filter(player=>player.type!=='goalkeeper'&&player.type!=='casual'&&player.primaryPosition!=='Goleiro');
 const monthlyPlayers=linePlayers.filter(player=>player.type!=='guest');
 const guestPlayers=linePlayers.filter(player=>player.type==='guest');
 return <div className="player-list-stack">
  <LinePlayerSection title="Mensalistas" description="Jogadores de linha mensalistas" players={monthlyPlayers} sort={sort} onSort={onSort} onEdit={onEdit}/>
  <LinePlayerSection title="Convidados" description="Jogadores de linha convidados" players={guestPlayers} sort={sort} onSort={onSort} onEdit={onEdit}/>
  <section><div className="player-list-title"><div><h2>Goleiros</h2><p>Goleiros mensalistas e avulsos · defesas, posicionamento, jogo com os pés, segurança e liderança</p></div><b>{goalkeepers.length}</b></div><div className="admin-card table player-table"><div className="tr player-tr goalkeeper-tr th"><PlayerSortHeader label="Goleiro" sortKey="name" sort={sort} onSort={onSort}/><PlayerSortHeader label="Tipo" sortKey="type" sort={sort} onSort={onSort}/><PlayerSortHeader label="Defesas" sortKey="skill" sort={sort} onSort={onSort}/><PlayerSortHeader label="Posicionamento" sortKey="primaryRating" sort={sort} onSort={onSort}/><PlayerSortHeader label="Jogo com os Pés" sortKey="secondaryRating" sort={sort} onSort={onSort}/><PlayerSortHeader label="Segurança" sortKey="fourthRating" sort={sort} onSort={onSort}/><PlayerSortHeader label="Liderança" sortKey="fifthRating" sort={sort} onSort={onSort}/><PlayerSortHeader label="Momentum" sortKey="momentum" sort={sort} onSort={onSort}/><PlayerSortHeader label="Status" sortKey="active" sort={sort} onSort={onSort}/></div>{goalkeepers.length?goalkeepers.map(player=><button className="tr player-tr goalkeeper-tr" key={player.id} onClick={()=>onEdit(player)}><PlayerIdentity player={player}/><span>{playerTypeLabel(player.type)}</span><span>{player.skill.toFixed(1)}</span><span>{(player.goalkeeperPositioning??player.speed).toFixed(1)}</span><span>{(player.goalExit??player.marking??3).toFixed(1)}</span><span>{(player.goalkeeperSafety??3).toFixed(1)}</span><span>{(player.goalkeeperLeadership??3).toFixed(1)}</span><PlayerMomentum player={player}/><PlayerStatus player={player}/></button>):<PlayerTableEmpty/>}</div></section>
 </div>
}
function LinePlayerSection({title,description,players,sort,onSort,onEdit}:{title:string;description:string;players:Player[];sort:PlayerSort;onSort:(key:PlayerSortKey)=>void;onEdit:(player:Player)=>void}){return <section><div className="player-list-title"><div><h2>{title}</h2><p>{description} · físico, técnica, marcação, inteligência tática e competitividade</p></div><b>{players.length}</b></div><div className="admin-card table player-table"><div className="tr player-tr line-player-tr th"><PlayerSortHeader label="Jogador" sortKey="name" sort={sort} onSort={onSort}/><PlayerSortHeader label="Tipo" sortKey="type" sort={sort} onSort={onSort}/><PlayerSortHeader label="Posição" sortKey="position" sort={sort} onSort={onSort}/><PlayerSortHeader label="Físico" sortKey="primaryRating" sort={sort} onSort={onSort}/><PlayerSortHeader label="Técnica" sortKey="skill" sort={sort} onSort={onSort}/><PlayerSortHeader label="Marcação" sortKey="secondaryRating" sort={sort} onSort={onSort}/><PlayerSortHeader label="Inteligência Tática" sortKey="fourthRating" sort={sort} onSort={onSort}/><PlayerSortHeader label="Competitividade" sortKey="fifthRating" sort={sort} onSort={onSort}/><PlayerSortHeader label="Momentum" sortKey="momentum" sort={sort} onSort={onSort}/><PlayerSortHeader label="Status" sortKey="active" sort={sort} onSort={onSort}/></div>{players.length?players.map(player=><button className="tr player-tr line-player-tr" key={player.id} onClick={()=>onEdit(player)}><PlayerIdentity player={player}/><span>{player.type==='guest'?'Convidado':'Mensalista'}</span><span>{player.primaryPosition}</span><span>{player.speed.toFixed(1)}</span><span>{player.skill.toFixed(1)}</span><span>{(player.marking??3).toFixed(1)}</span><span>{(player.tacticalIntelligence??3).toFixed(1)}</span><span>{(player.competitiveness??3).toFixed(1)}</span><PlayerMomentum player={player}/><PlayerStatus player={player}/></button>):<PlayerTableEmpty/>}</div></section>}
function PlayerIdentity({player}:{player:Player}){return <span className="person"><AdminAvatar player={player}/><b>{player.displayName}<small>{player.nickname}</small></b></span>}
function PlayerMomentum({player}:{player:Player}){return <span className={(player.momentum??0)>0?'momentum positive':(player.momentum??0)<0?'momentum negative':'momentum'}>{(player.momentum??0)>0?'+':''}{(player.momentum??0).toFixed(1)}</span>}
function PlayerStatus({player}:{player:Player}){return <span className={player.active?'status active':'status'}>{player.active?'Ativo':'Inativo'}</span>}
function PlayerTableEmpty(){return <div className="player-table-empty">Nenhum jogador encontrado nesta lista.</div>}
function PlayerSortHeader({label,sortKey,sort,onSort}:{label:string;sortKey:PlayerSortKey;sort:PlayerSort;onSort:(key:PlayerSortKey)=>void}){const active=sort.key===sortKey,direction=active?sort.direction:null;return <button type="button" className={active?'sort-header active':'sort-header'} onClick={()=>onSort(sortKey)} aria-label={`Ordenar por ${label}${active?`, atualmente ${direction==='asc'?'crescente':'decrescente'}`:''}`} title={`Ordenar por ${label}`}><span>{label}</span><i aria-hidden="true">{direction==='asc'?'↑':direction==='desc'?'↓':'↕'}</i></button>}
function comparePlayers(a:Player,b:Player,sort:PlayerSort){const aValue=playerSortValue(a,sort.key),bValue=playerSortValue(b,sort.key);let result=typeof aValue==='number'&&typeof bValue==='number'?aValue-bValue:String(aValue).localeCompare(String(bValue),'pt-BR',{sensitivity:'base',numeric:true});if(result===0)result=a.displayName.localeCompare(b.displayName,'pt-BR',{sensitivity:'base',numeric:true});return sort.direction==='asc'?result:-result}
function playerSortValue(player:Player,key:PlayerSortKey){const goalkeeper=player.type==='goalkeeper'||player.type==='casual'||player.primaryPosition==='Goleiro';switch(key){case'name':return player.displayName;case'type':return playerTypeLabel(player.type);case'position':return player.primaryPosition;case'primaryRating':return goalkeeper?(player.goalkeeperPositioning??player.speed):player.speed;case'skill':return player.skill;case'secondaryRating':return goalkeeper?(player.goalExit??player.marking??3):(player.marking??3);case'fourthRating':return goalkeeper?(player.goalkeeperSafety??3):(player.tacticalIntelligence??3);case'fifthRating':return goalkeeper?(player.goalkeeperLeadership??3):(player.competitiveness??3);case'momentum':return player.momentum??0;case'active':return player.active?1:0}}
function RatingSlider({label,help,value,onChange}:{label:string;help?:string;value:number;onChange:(value:number)=>void}){const id=`discipline-${label.toLowerCase().replace(/[^a-z0-9]+/g,'-')}`;return <label className="rating-slider"><span>{label}{help&&<HelpTip id={id} text={help}/>}</span><input type="range" min="1" max="5" step="0.1" value={value} onChange={event=>onChange(Math.round(Number(event.target.value)*10)/10)}/><output>{Number(value).toFixed(1)}</output><small><span>1</span><span>5</span></small></label>}
